INSERT INTO destinations (id, slug, name, region, summary, body_md, meta_title, meta_description, lat, lng, published) VALUES ('dest_nadi', 'nadi', 'Nadi', 'Western Fiji', 'Fiji''s main gateway -- the international airport town on Viti Levu''s west coast, and the base for most day tours, transfers, and adventure activities.', 'Nadi (pronounced "Nandi") is where almost every visitor to Fiji first arrives -- Nadi International Airport is the country''s main air gateway, and the town has grown around serving that traffic with hotels, tour operators, and transfer services.' || char(10) || char(10) || 'Beyond the airport, Nadi blends Fijian and Indo-Fijian culture -- it''s home to the Sri Siva Subramaniya Temple, the largest Hindu temple in the Southern Hemisphere, alongside markets and handicraft shops. Most travelers use Nadi as a base for a day or two before heading to Denarau, the Coral Coast, or the outer islands.' || char(10) || char(10) || 'It''s also the starting point for most of Viti Levu''s adventure tours -- cultural nights, ATV trails, zip lines, and full-day excursions typically depart from Nadi hotels with transfers included.', 'Nadi, Fiji -- Tours, Transfers & Travel Guide', 'Everything to know about Nadi, Fiji''s main airport town: cultural tours, ATV adventures, zip lining, and how to get around.', -17.8, 177.45, 1), ('dest_natadola_beach', 'natadola-beach', 'Natadola Beach', 'Coral Coast, Fiji', 'Regularly named one of Fiji''s best beaches -- a long stretch of golden sand on the Coral Coast, about an hour from Nadi.', 'Natadola Beach sits on Viti Levu''s Coral Coast, roughly 40 minutes to an hour south of Nadi. It''s consistently rated among Fiji''s most beautiful beaches -- a long curve of fine golden sand backed by resorts, with calm water protected by an offshore reef.' || char(10) || char(10) || 'Unlike Nadi''s busier waterfront, Natadola is a day-trip destination rather than a town -- most visitors come for a few hours of beach time, often combined with horse riding along the sand, one of the most popular activities here.' || char(10) || char(10) || 'It''s a manageable add-on to a Nadi-based trip rather than a place to base a whole stay, since accommodation directly on the beach is limited.', 'Natadola Beach, Fiji -- One of Fiji''s Best Beaches', 'Why Natadola Beach is rated one of Fiji''s top beaches, plus horse riding tours and how to get there from Nadi.', -18.19, 177.78, 1), ('dest_sigatoka', 'sigatoka', 'Sigatoka', 'Coral Coast, Fiji', 'A river town on the Coral Coast, known for its market, sand dunes, and the inland Naihehe Cave tour.', 'Sigatoka sits at the mouth of the Sigatoka River on Viti Levu''s Coral Coast, about an hour south of Nadi. It''s a working town rather than a resort strip -- known locally for its produce market and as the gateway to the Sigatoka Sand Dunes, Fiji''s first national park.' || char(10) || char(10) || 'Inland from the town, the Sigatoka Valley -- sometimes called Fiji''s "salad bowl" -- leads toward Naihehe Cave, a limestone cave system historically used by the Nabilebile clan and now visited on guided full-day tours from Nadi.' || char(10) || char(10) || 'Sigatoka works well as a stop between Nadi and the Coral Coast resorts, or as the access point for a cave tour, rather than a standalone beach destination.', 'Sigatoka, Fiji -- Sand Dunes, River & Naihehe Cave Guide', 'Sigatoka travel guide: the sand dunes, river valley, market, and the Naihehe Cave tour from Nadi.', -18.14, 177.5, 1), ('dest_coral_coast', 'coral-coast', 'Coral Coast', 'Southern Viti Levu, Fiji', 'The resort-lined stretch of Viti Levu''s southern coastline between Nadi and Suva, known for reef breaks and beachfront hotels.', 'The Coral Coast is the name given to roughly 50 kilometres of Viti Levu''s southern coastline, running from around Sigatoka toward Pacific Harbour. It''s one of Fiji''s longest-established resort areas, with beachfront hotels facing a fringing reef just offshore.' || char(10) || char(10) || 'Compared to Denarau or the outer islands, the Coral Coast has a more local feel -- small villages sit alongside the resorts, and activities lean toward horse riding, village visits, and river or cave tours into the hills rather than water sports.' || char(10) || char(10) || 'It''s best visited as part of a wider Viti Levu road trip rather than a single day trip, since the resorts and attractions are spread along the whole stretch.', 'Coral Coast, Fiji -- Resorts, Reef & Village Tours Guide', 'A guide to Viti Levu''s Coral Coast: resorts, reef, horse riding, and village tours between Nadi and Suva.', -18.2, 177.7, 1);

INSERT INTO tours (id, slug, name, category, destination_id, description, price_from, currency, duration_minutes, booking_url, active) VALUES ('tour_nadi_cultural_night', 'nadi-cultural-night-tour', 'Nadi Cultural Night Tour', 'cultural', 'dest_nadi', 'Kava ceremony, meke dancing, fire dance, and a traditional lovo (underground oven) feast. Real live tour on fijitourtransfers.com -- rated 5.0 from 6 reviews at last check.', 135, 'AUD', 240, 'https://fijitourtransfers.com/st_tour/nadi-cultural-night-tour-fiji-up-to-15-off/', 1), ('tour_nadi_atv', 'nadi-off-road-atv-adventure', 'Nadi Off-Road ATV Bike Adventure', 'adventure', 'dest_nadi', 'Quad-bike ride through jungle trails, sugarcane fields, and hilltop viewpoints over the Mamanuca Islands. Real live tour on fijitourtransfers.com -- rated 5.0 from 5 reviews at last check.', 299, 'AUD', 300, 'https://fijitourtransfers.com/st_tour/nadi-off-road-atv-bike-adventure-day-tour-fiji/', 1), ('tour_nadi_full_day', 'nadi-full-day-tour', 'Nadi Full Day Tour', 'sightseeing', 'dest_nadi', 'A full day covering several of Nadi''s highlights in one trip. Real live tour on fijitourtransfers.com -- rated 4.7 from 8 reviews at last check.', 180, 'AUD', 360, 'https://fijitourtransfers.com/st_tour/nadi-full-day-tour-up-to-40-off-in-fiji/', 1), ('tour_nadi_zipline', 'nadi-zip-line-tour', 'Nadi Zip Line Tour', 'adventure', 'dest_nadi', 'Canopy zip line course through Nadi''s jungle hills. Real live tour on fijitourtransfers.com -- rated 5.0 from 10 reviews at last check.', 221, 'AUD', 180, 'https://fijitourtransfers.com/st_tour/nadi-zip-line-tour-fiji-2026/', 1), ('tour_natadola_horse_riding', 'natadola-beach-horse-riding', 'Natadola Beach Horse Riding', 'horse-riding', 'dest_natadola_beach', 'A guided horse ride along Natadola''s sand, suitable for beginners. Real live tour on fijitourtransfers.com -- rated 4.8 from 10 reviews at last check.', 100, 'AUD', 150, 'https://fijitourtransfers.com/st_tour/natadola-beach-combinational-horse-riding-fiji/', 1), ('tour_naihehe_cave', 'naihehe-cave-tour-sigatoka', 'Explore Naihehe Cave Tour', 'caving', 'dest_sigatoka', 'A guided full-day trip into the Sigatoka Valley to explore the Naihehe limestone cave system. Real live tour on fijitourtransfers.com -- rated 4.9 from 8 reviews at last check.', 160, 'AUD', 360, 'https://fijitourtransfers.com/st_tour/explore-naihehe-cave-tour-sigatoka-fiji/', 1), ('tour_coral_coast_horse_riding', 'coral-coast-mountain-horse-riding', 'Coral Coast Mountain View Horse Riding', 'horse-riding', 'dest_coral_coast', 'A shorter horse ride through the hills behind the Coral Coast with views over the coastline. Real live tour on fijitourtransfers.com -- rated 5.0 from 5 reviews at last check.', 150, 'AUD', 90, 'https://fijitourtransfers.com/st_tour/coral-coast-fiji-mountain-view-horse-riding-2026/', 1);
